#include <vector>
using namespace std;

class Solution {
public:
    void moveZeroes(vector<int>& nums) {
        int insert_pos = 0;
        for (int num : nums) {
            if (num != 0) {
                nums[insert_pos++] = num;
            }
        }
        while (insert_pos < (int)nums.size()) {
            nums[insert_pos++] = 0;
        }
    }
};

